import string
import re


class _DefaultDict(dict):
    """
    Dictionary, which returns a placeholder "{x}" for a non-existing key "x".

    It is used in string formatting to only replace a subset of all occurring placeholders.
    """

    def __missing__(self, key):
        return "{%s}" % key


def partial_format(format_string, *args, **kwargs):
    """
    Format a string partially.

    This function is similar to str.format(), but it allows to provide values for only
    a subset of the placeholders occurring in the format string, keeping those placeholders,
    for which there is no value available yet.

    Usage:

        partial_format("{a} {b}", b=1) -> '{a} 1'
    """
    return string.Formatter().vformat(format_string, args, _DefaultDict(**kwargs))


def camel_case(snake_case):
    return re.sub(
        r"(?:^|_)(.)",
        lambda match: match.group(1).upper(),
        snake_case)
